{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/feature-showcase.json
    Features as cards under a centered heading. Axes: item (picture: a picture on top, then the title, the text and a read link; panel: a muted panel with a large glyph on top, then the title and the text), cols (3, 4), tone.
    Props (p): id, title, lead, features, empty, more, item, cols, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_features = ($p['features'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_more = ($p['more'] ?? null)}
{var $v_item = ($p['item'] ?? 'picture')}
{var $v_cols = ($p['cols'] ?? '3')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_8}
  {if og_t(og_eq(og_len($v_features), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'layout-grid', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_7}
      {foreach og_l($v_features) as $v_f}
        {capture $c_6}
          {if og_t(og_eq($v_item, 'picture'))}
            {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_f, ['title'])]])|noescape}
          {else}
            {capture $c_1}
              {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_f, ['icon'])), 'size' => 32])|noescape}
            {/capture}
            {=og_include('compose/Box.latte', ['class' => 'flex aspect-video items-center justify-center rounded bg-muted text-foreground', 'attrs' => og_attrs(['data-testid', 'showcase-panel']), 'children' => (string) $c_1])|noescape}
          {/if}
          {capture $c_5}
            {capture $c_2}
              {=og_text(og_get($v_f, ['title']))}
            {/capture}
            {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'base', 'weight' => 'semibold', 'children' => (string) $c_2])|noescape}
            {capture $c_3}
              {=og_text(og_get($v_f, ['text']))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_3])|noescape}
            {if og_t(og_eq($v_item, 'picture'))}
              {capture $c_4}
                {=og_text($v_more)}
                {=og_include('icons/LucideIcon.latte', ['name' => 'arrow-right', 'size' => 16])|noescape}
              {/capture}
              {=og_include('blocks/menu-entry.latte', ['p' => ['href' => og_get($v_f, ['href']), 'className' => og_cnv(['mt-auto gap-2 pt-2 text-sm font-medium']), 'size' => 'sm', 'testid' => 'read'], 'children' => og_markup($c_4)])|noescape}
            {/if}
          {/capture}
          {=og_include('compose/CardContent.latte', ['class' => 'flex flex-1 flex-col gap-2', 'children' => (string) $c_5])|noescape}
        {/capture}
        {=og_include('compose/Card.latte', ['variant' => 'default', 'class' => 'h-full gap-4 overflow-hidden', 'attrs' => og_attrs(['data-testid', 'showcase-card']), 'children' => (string) $c_6])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_cols, '4')) ? 'grid grid-cols-1 gap-6 text-start sm:grid-cols-2 lg:grid-cols-4' : 'grid grid-cols-1 gap-6 text-start sm:grid-cols-2 lg:grid-cols-3')), 'children' => (string) $c_7])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'align' => 'center', 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_8)])|noescape}
